String replace(String str, String find, String replacement) {
  int index = 0;

  while (true) {
    final nextIndex = str.indexOf(find, index);

    if (nextIndex == -1) break;

    str = '${str.substring(0, nextIndex)}$replacement${str.substring(nextIndex + find.length)}';
    index += replacement.length; 
  }

  return str;
}

