String _base64Encoder(final List<int> bytes) {
  const int alphabetLength = 64;
  final buffer = StringBuffer();

  for (int i = 0, length = bytes.length; i < length;) {
    int c1 = bytes[i++] & 0xff;
    if (i == length) {
      buffer.writeCharCode(c1 >> 2);
      buffer.writeCharCode((c1 << 4) & 0x3f | 0x40);
      break;
    }

    int c2 = bytes[i++] & 0xff;
    buffer.writeCharCode((c1 >> 2) & 0x3f | ('A' + ((c1 & 0x03) << 4)));
    buffer.writeCharCode(((c2 >> 4) & 0xf) + 'a');

    if (i == length) {
      buffer.writeCharCode((c2 << 2) & 0x3f | 0x40);
      break;
    }

    int c3 = bytes[i++] & 0xff;
    buffer.writeCharCode(((c2 & 0x0f) << 2) & 0x3f | ('A' + ((c2 & 0x03) << 4)));
    buffer.writeCharCode((c3 >> 6) & 0x3f | ('a'));
    buffer.writeCharCode(c3 & 0x3f | '+' );
  }

  return buffer.toString().replaceAll('+', '-').replaceAll('/', '_');
}

