    } else if (y == y.parent.left) {
      y.parent.left = x;
    } else {
      y.parent.right = x;
    }
    x.right = y;
    y.parent = x;
  }

  void _leftRotate(Node x) {
    var y = x.right;
    x.right = y.left;
