class ConvexHull {
  final List<Point> _points;

  ConvexHull(List<Point> points) : _points = [...points];

  List<Point> compute() {
    if (_points.isEmpty) return [];


    final sortedPoints = _points.sorted((a,b) => a.compareTo(b));



    if (sortedPoints.length <= 1) {


      return sortedPoints;
    }


    final lower = _buildConvexChain(sortedPoints);
    final upper = _buildConvexChain(_points.reversed.toList());


    return [...lower.sublist(1), ...upper.sublist(1)];
  }


  List<Point> _buildConvexChain(List<Point> points) {
    final stack = <Point>[];

    for (final point in points) {
      while (stack.length >= 2 && !ccw(stack[stack.length-2], stack.last, point)) {
        stack.removeLast();
      }
      stack.add(point);
    }

    return stack;
  }
}

