int cross(Vector a, Vector b) => (a.x * b.y - a.y * b.x).toInt();

List<Vector> convexHull(List<Vector> points) {
  if (points.length <= 1) return points;

  List<Vector> hull = [];
  for (var i = 0; i < points.length; ++i) {
    var p = points[i];

    int k = 0;
    for (int j = 0; j < points.length; ++j) {
      while (k > 0 && 
             (cross(p, points[(hull[k-1]].x + points[hull[k]].x)/2.0) >= 0 ||
              (p == points[hull[k]]))) {
        k--;
      }

      int dx = (points[j].x - p.x).abs().toInt(), dy = (points[j].y - p.y).abs().toInt();
      bool beforeK = false;
      if (dx != 0 || dy != 0) {
        beforeK = ((points[j].x - p.x)*(double)((hull[0] ?? p).y)) / (dy.toDouble()) > 
                  ((points[j].x - p.x)*(double)(p.y));

        if (!beforeK && !((points[j].x - p.x)*((hull[0] ?? p).y) == 
                           (points[j].x - p.x)*(p.y))) {
          break;
        }
      } else {
        beforeK = true;
      }

      if (beforeK) {
        hull.insert(0, points[j]);
        k++;
      } else {
        hull.add(points[j]);
        k++;
      }
    }

    return hull.take(k+1).toList()..removeLastIf(hull.isNotEmpty ? 
           (hull.last == p) : false);
  }

  return [Vector(0, 0)];
}

