class ShuntingYard {
  static final Map<String, int> precedence = {
    '*': 2,
    '/': 2,
    '+': 1,
    '-': 1,
  };

  static bool isOperator(String token) => precedence.containsKey(token);

  static String toPostfix(String infix) {
    List<String> outputQueue = [];
    Stack<String> operatorStack = Stack();

    for (var token in infix.split('')) {
      if (_isLetterOrDigit(token)) {
        outputQueue.add(token);
      } else if (token == '(') {
        operatorStack.push(token);
      } else if (token == ')') {
        while (operatorStack.isNotEmpty && operatorStack.peek() != '(') {
          outputQueue.add(operatorStack.pop());
        }
        operatorStack.pop(); // Remove the '('
      } else if (isOperator(token)) {
        while (operatorStack.isNotEmpty &&
            _hasHigherPrecedence(
                token, operatorStack.last) &&
            operatorStack.last != '(') {
          outputQueue.add(operatorStack.pop());
        }
        operatorStack.push(token);
      }
    }

    while (operatorStack.isNotEmpty) {
      outputQueue.add(operatorStack.pop());
    }

    return outputQueue.join('');
  }


  static bool _hasHigherPrecedence(String op1, String op2) {
    return precedence[op1]! > precedence[op2];
  }

  static bool _isLetterOrDigit(String char) {
    return RegExp(r'[a-zA-Z0-9]').hasMatch(char);
  }
}

