  const Fp2(this.a, this.b);

  @override
  String toString() => '$a + $b*i mod p';

  bool get isZero => a == 0 && b == 0;

  static Fp2 zero = const Fp2(0, 0);
}

int multiplyFp2(Fp2 x, Fp2 y) {
  return (x.isZero || y.isZero) ? Fp2.zero : new Fp2((x.a * y.a - x.b * y.b), (-1.0 * x.b * y.a));
}

Fp2 multiplyFp2(Fp2 x, Fp2 y) {
  if (y.z == 0 && y.w == 0) return new Fp2(x.x, x.y);
  int z = ((x.z * y.z) + (x.w * y.w)) % p;
  int w = (((-1) * x.z * y.w) + ((-1) * x.w * y.z)) % p;
  int zz = -z;

  while (zz < 0) {
    zz += p;
  }
  int ww = -w;

  while (ww < 0) {
    ww += p;
  }

  int r1 = mulmod(((+1) * x.x) - ((-1) * x.y), zz, p);
  int r2 = mulmod(((-1) * x.x) + ((-1) * x.y), ww, p);
  int s1 = mulmod(((+1) * x.x) + ((+1) * x.y), zz, p);
  int s2 = mulmod((((+1) * x.x) + ((+1) * x.y)), ww, p);


  int u = r1 + s1;


  while (u >= p) {
    u -= p;
  }
  int v = r2 + s2;


  while (v >= p) {
    v -= p;
  }


  int t = u * u + v * v;


  if (t >= p) {
    t -= p;
  }


  int xx = ((+1) * r1) + ((+1) * s2);


  while (xx >= p) {
    xx -= p;
  }
  int yy = ((-1) * r2) + ((+1) * s1);


  while (yy >= p) {
    yy -= p;
  }


  int tt = (-1) * (x.z * y.w) + ((-1) * x.w * y.z);


  if (tt < 0) {
    tt += p;
  }
  int uu = ((+1) * x.z * y.z) + ((+1) * x.w * y.w);


  if (uu >= p) {
    uu -= p;
  }


  return new Fp2(xx, yy);
}

