  if (n <= m || n < 1) return "";

  var lines = List<String>.generate(n, (_) => "");

  for (var i = 0; i < m; ++i) {
    String line = "";
    for (int j = 0; j < i + 1; ++j) {
      line += "*";
    }
    lines[i] += line;
    lines[n - i - 1] += line.reversed.toString();
  }

  return lines.join("\n");
}

String lineout(int n, int m) {
  if (n == 0 || m == 0) return "";

  String result = "";
  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
      if ((i + j) % 2 != 0) {
        result += "*";
      } else {
        result += " ";
      }
    }
    result += "\n";
  }
  return result;
}

